use std::fs;
fn replace(s:&mut String,a:&str,b:&str){assert!(s.contains(a),"missing:{a}");*s=s.replace(a,b);}
fn main(){let mut s=fs::read_to_string("experiment.rs").unwrap();replace(&mut s,"/zopro-perf-work/euler-fused-columns","/zopro-perf-work/inverse-finish-sdk");let start=s.find("fn pins()").unwrap();let end=s.find("fn prepare()").unwrap();s.replace_range(start..end,&format!("{}\n{}\n",fs::read_to_string("sdk-pins.txt").unwrap(),fs::read_to_string("sdk-build-plan.txt").unwrap()));let start=s.find("    let a = read(r.join(\"native/candidate/artifacts.json\"));").unwrap();let end=s[start..].find("    assert_eq!(\n        hash(CONTROL)").unwrap()+start;s.replace_range(start..end,r#"    for label in["off","on"]{let a=read(r.join(format!("native/{label}/artifacts.json")));for(p,h)in a["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pin(&mut pins,p);}let binary=r.join(format!("native/{label}-sdk"));assert_eq!(hash(&binary),a["binary_sha256"].as_str().unwrap());pin(&mut pins,binary);pin(&mut pins,r.join(format!("native/{label}/artifacts.json")));pin(&mut pins,r.join(format!("frozen-{label}-cargo.jsonl")));}
    let off=read(r.join("native/off/artifacts.json"));let on=read(r.join("native/on/artifacts.json"));assert_ne!(off["binary_sha256"],on["binary_sha256"]);for name in["zopro_bn254","zopro_core"]{assert_ne!(hash(off["libraries"][name].as_str().unwrap()),hash(on["libraries"][name].as_str().unwrap()));}
"#);
replace(&mut s,"/zopro-perf-work/euler-compact/","/zopro-perf-work/euler-fused-columns/");replace(&mut s,"assert_eq!(prior.len(), 12685)","assert_eq!(prior.len(), 12686)");replace(&mut s,"assert_eq!(prior.len(), 12686);\n    save", "assert_eq!(prior.len(), 12785);\n    save");replace(&mut s,"candidate.display().to_string()","r.join(format!(\"native/{label}-sdk\")).display().to_string()");let start=s.find("        env[\"ZOPRO_CPU_EULER_FUSED_COLUMNS\"]").unwrap();let end=s[start..].find("        let mask =").unwrap()+start;s.replace_range(start..end,"");fs::write("experiment.rs",s).unwrap();}
